const config={key:'request',steps:[{key:'q',questionKey:'q',kind:'question',required:true}]};
afterEach(()=>{cleanup();vi.unstubAllGlobals();});
it('uses pinned questions and identical body/key for ambiguous retry, never exposes token or confirmation',async()=>{
 vi.stubGlobal('location',{protocol:'https:'});const bodies:string[]=[];const calls:RequestInit[]=[];
 vi.stubGlobal('fetch',vi.fn(async(url:string,options:RequestInit)=>{calls.push(options);if(url.includes('/availability'))return availabilityResponse(url);if(url.includes('/sessions'))return new Response(JSON.stringify({ok:true,data:{sessionToken:token,expiresAt:'2035-01-01T00:00:00Z',render:{versionId:id,config,service}}}));bodies.push(options.body as string);if(bodies.length===1)throw Error('connection interrupted with private-server-details');return new Response(JSON.stringify({ok:true,data:{reference:bookingReference,state:'draft',confirmed:false}}));}));
 render(<HostedFlow installationId={id} apiUrl="https://api.example"/>);await screen.findByText('Published service');fireEvent.change(screen.getByLabelText('Choose an option'),{target:{value:'a'}});fireEvent.change(screen.getByLabelText('Your name'),{target:{value:'Synthetic Person'}});fireEvent.change(screen.getByLabelText('Email'),{target:{value:'synthetic@example.test'}});fireEvent.change(screen.getByLabelText('Requested date'),{target:{value:'2030-01-01'}});await waitFor(()=>expect(screen.getByLabelText('Available time')).toBeEnabled());fireEvent.change(screen.getByLabelText('Available time'),{target:{value:slotStart}});fireEvent.click(screen.getByText('Send unconfirmed request'));await screen.findByText('Retry the same request');expect(screen.getByLabelText('Your name')).toBeDisabled();fireEvent.click(screen.getByText('Retry the same request'));await screen.findByText('Request saved');expect(bodies).toHaveLength(2);expect(JSON.parse(bodies[0]!).requestedStart).toBe(slotStart);expect(bodies[0]).toBe(bodies[1]);expect(JSON.parse(bodies[0]!)).not.toHaveProperty('tenantId');expect(JSON.parse(bodies[0]!)).not.toHaveProperty('serviceId');expect(calls[1]!.headers).toMatchObject({Authorization:'Bearer '+token});expect(document.body.textContent).not.toContain(token);expect(document.body.textContent).not.toContain('private-server-details');expect(screen.getByText(/Your request is unconfirmed/)).toBeTruthy();
});
