it('offers a cross-midnight slot from a full-day response while omitting next-day boundary starts',async()=>{
 vi.stubGlobal('location',{protocol:'https:'});const {createAvailabilityEngine}=await import('@lumin/core');let expected:string[]=[];let crossMidnight='';
 vi.stubGlobal('fetch',vi.fn(async(url:string)=>{if(url.includes('/availability')){const query=new URL(url).searchParams,from=query.get('from')!,to=query.get('to')!;const browserZone=Intl.DateTimeFormat().resolvedOptions().timeZone;
 const tenantTimezone=browserZone==='America/Los_Angeles'?'Asia/Kolkata':'America/Los_Angeles';
 const slots=createAvailabilityEngine().getSlots({tenantTimezone,serviceId:id,durationMinutes:30,policy:{leadTimeMinutes:0,horizonDays:60,slotIntervalMinutes:15},rules:Array.from({length:7},(_,weekday)=>({id,tenantId:id,serviceId:id,weekday,startMinute:0,endMinute:1440,capacity:1})),overrides:[],existing:[],now:new Date(Date.parse(from)-86400000).toISOString(),from,to});
 expected=slots.filter(slot=>Date.parse(slot.start)<Date.parse(to)).map(slot=>slot.start);crossMidnight=slots.find(slot=>Date.parse(slot.start)<Date.parse(to)&&Date.parse(slot.end)>Date.parse(to))!.start;expect(slots.some(slot=>Date.parse(slot.start)===Date.parse(to))).toBe(true);
 return new Response(JSON.stringify({ok:true,data:{schemaVersion:1,serviceId:id,durationMinutes:30,slots}}));}return new Response(JSON.stringify({ok:true,data:{sessionToken:token,expiresAt:'2035-01-01T00:00:00Z',render:{versionId:id,config,service}}}));}));
 render(<HostedFlow installationId={id} apiUrl="https://api.example"/>);await screen.findByText('Published service');fireEvent.change(screen.getByLabelText('Requested date'),{target:{value:'2030-01-01'}});await waitFor(()=>expect(screen.getByLabelText('Available time')).toBeEnabled());const selector=screen.getByLabelText('Available time') as HTMLSelectElement;expect(Array.from(selector.options).slice(1).map(option=>option.value)).toEqual(expected);fireEvent.change(selector,{target:{value:crossMidnight}});expect(screen.getByText('Send unconfirmed request')).toBeEnabled();
});
