it('V5 freezes private information/body/key through an unknown request and keeps hold/payment authority separate',async()=>{
 vi.stubGlobal('location',{protocol:'https:'});const bodies:string[]=[];let paymentCalls=0;const transport=fieldTransport(async options=>{bodies.push(options.body as string);if(bodies.length===1)throw Error('PRIVATE-FIELD-ERROR');return new Response(JSON.stringify({ok:true,data:{reference:bookingReference,state:'draft',confirmed:false}}));},async()=>{paymentCalls++;return new Response(JSON.stringify({ok:true,data:paymentData}));});vi.stubGlobal('fetch',transport);render(<HostedFlow installationId={id} apiUrl="https://api.example"/>);await fillFieldRequest('Private entry');fireEvent.click(screen.getByText('Send unconfirmed request'));await screen.findByText('Retry the same request');expect(screen.getByLabelText('Entry instructions')).toBeDisabled();expect(screen.getByLabelText('Notes (optional)')).toBeDisabled();fireEvent.change(screen.getByLabelText('Entry instructions'),{target:{value:'Changed'}});fireEvent.change(screen.getByLabelText('Notes (optional)'),{target:{value:'New'}});fireEvent.click(screen.getByText('Retry the same request'));await screen.findByText('Request saved');expect(bodies[1]).toBe(bodies[0]);expect(JSON.parse(bodies[0]!).customerAnswers).toEqual({custom_access:'Private entry'});expect(JSON.parse(bodies[0]!).answers).toEqual({});expect(JSON.parse(bodies[0]!)).not.toHaveProperty('price');expect(paymentCalls).toBe(0);expect(screen.queryByText('Test booking confirmed')).toBeNull();expect(document.body.textContent).not.toContain('Private entry');expect(document.body.textContent).not.toContain('PRIVATE-FIELD-ERROR');
 fireEvent.click(screen.getByText('Reserve selected time'));fireEvent.click(await screen.findByText('Make staging test payment'));await screen.findByText('Test booking confirmed');expect(paymentCalls).toBe(1);expect(transport.mock.calls.filter(([url])=>url.includes('/sessions'))).toHaveLength(1);expect(transport.mock.calls.find(([url])=>url.endsWith('/hold'))?.[1].body).toBe('{}');expect(transport.mock.calls.find(([url])=>url.endsWith('/mock-payment'))?.[1].body).toBe('{}');expect(document.body.textContent).not.toContain(token);expect(document.body.textContent).not.toContain('Private entry');
});
it('V5 expires an unknown request without sending another request or granting reservation',async()=>{
 vi.stubGlobal('location',{protocol:'https:'});const now=vi.spyOn(Date,'now').mockReturnValue(Date.parse('2029-12-01T00:00:00Z'));const request=vi.fn(async()=>{throw Error('Ambiguous request');}),transport=fieldTransport(request,undefined,'2029-12-01T00:10:00Z');vi.stubGlobal('fetch',transport);
 try{render(<HostedFlow installationId={id} apiUrl="https://api.example"/>);await fillFieldRequest();fireEvent.click(screen.getByText('Send unconfirmed request'));await screen.findByText('Retry the same request');now.mockReturnValue(Date.parse('2029-12-01T00:10:00Z'));fireEvent.submit(screen.getByText('Retry the same request').closest('form')!);await screen.findAllByText('Your session expired. Reload this page to start again.');expect(request).toHaveBeenCalledOnce();expect(screen.queryByText('Reserve selected time')).toBeNull();expect(screen.queryByText('Test booking confirmed')).toBeNull();}finally{now.mockRestore();}
});
it('V5 drops late private request results and fields when installation context changes',async()=>{
 vi.stubGlobal('location',{protocol:'https:'});let finish!:(response:Response)=>void;const second='22222222-2222-4222-8222-222222222222',transport=fieldTransport(()=>new Promise<Response>(r=>finish=r));vi.stubGlobal('fetch',vi.fn(async(url:string,options:RequestInit)=>url.includes('/'+second+'/sessions')?new Response(JSON.stringify({ok:true,data:{sessionToken:token,expiresAt:'2035-01-01T00:00:00Z',render:paidRender}})):transport(url,options)));const {rerender}=render(<HostedFlow installationId={id} apiUrl="https://api.example"/>);await fillFieldRequest('Private entry');fireEvent.click(screen.getByText('Send unconfirmed request'));await waitFor(()=>expect(finish).toBeTypeOf('function'));rerender(<HostedFlow installationId={second} apiUrl="https://api.example"/>);await screen.findByText('Paid housekeeping');finish(new Response(JSON.stringify({ok:true,data:{reference:bookingReference,state:'draft',confirmed:false}})));await waitFor(()=>expect(screen.queryByText('Request saved')).toBeNull());expect(screen.queryByLabelText('Entry instructions')).toBeNull();expect(screen.queryByText(bookingReference)).toBeNull();expect(document.body.textContent).not.toContain('Private entry');expect(screen.getByText('Send unconfirmed request')).toBeDisabled();
});
it.each(['unknown version','unsupported kind','extra price','duplicate ID','unsafe label','unapproved design'])('V5 rejects %s without a legacy renderer or a second session acquisition',async kind=>{
 vi.stubGlobal('location',{protocol:'https:'});const f=fieldRender.customerFields[0]!;const invalid=kind==='unknown version'?{...fieldRender,renderSchemaVersion:6}:kind==='unapproved design'?{...fieldRender,publication:{...fieldRender.publication,presentation:{accentColor:'url(evil)',layout:'compact'}}}:{...fieldRender,customerFields:kind==='duplicate ID'?[f,f]:[{...f,...(kind==='unsupported kind'?{kind:'email'}:kind==='extra price'?{price:1}:{label:'bad\nlabel'})}]};const transport=fieldTransport(undefined,undefined,undefined,invalid);vi.stubGlobal('fetch',transport);render(<HostedFlow installationId={id} apiUrl="https://api.example"/>);await screen.findByRole('alert');expect(screen.queryByText('Send unconfirmed request')).toBeNull();expect(screen.queryByLabelText('Notes (optional)')).toBeNull();expect(transport).toHaveBeenCalledOnce();
});
it('V5 default client acquisition remains failclosed while Checkout opts in explicitly',async()=>{
 const transport=fieldTransport();const client=createFlowClient('https://api.example',false,transport as unknown as typeof fetch);await expect(client.session(id)).rejects.toMatchObject({code:'INTERNAL_ERROR'});expect(transport).toHaveBeenCalledOnce();
});

it('V5 moves keyboard focus to each verified receipt after explicit request and payment',async()=>{
 vi.stubGlobal('location',{protocol:'https:'});const transport=fieldTransport();vi.stubGlobal('fetch',transport);render(<HostedFlow installationId={id} apiUrl="https://api.example"/>);await fillFieldRequest();
 const submit=screen.getByRole('button',{name:'Send unconfirmed request'});submit.focus();fireEvent.click(submit);const saved=await screen.findByRole('heading',{name:'Request saved'});expect(saved).toHaveFocus();expect(saved).toHaveAttribute('tabindex','-1');
 fireEvent.click(screen.getByRole('button',{name:'Reserve selected time'}));const pay=await screen.findByRole('button',{name:'Make staging test payment'});pay.focus();fireEvent.click(pay);const confirmed=await screen.findByRole('heading',{name:'Test booking confirmed'});expect(confirmed).toHaveFocus();expect(transport.mock.calls.filter(([url])=>url.endsWith('/request'))).toHaveLength(1);expect(transport.mock.calls.filter(([url])=>url.endsWith('/mock-payment'))).toHaveLength(1);
});
it('V5 pending or failed writes do not move focus to an unverified receipt',async()=>{
 vi.stubGlobal('location',{protocol:'https:'});let rejectRequest!:(error:Error)=>void;const request=vi.fn(()=>new Promise<Response>((_resolve,reject)=>rejectRequest=reject)),transport=fieldTransport(request);vi.stubGlobal('fetch',transport);render(<HostedFlow installationId={id} apiUrl="https://api.example"/>);await fillFieldRequest();
 const heading=screen.getByRole('heading',{name:'Saved customer field form'}),submit=screen.getByRole('button',{name:'Send unconfirmed request'});submit.focus();fireEvent.click(submit);await waitFor(()=>expect(request).toHaveBeenCalledOnce());expect(screen.queryByRole('heading',{name:'Request saved'})).toBeNull();expect(heading).not.toHaveFocus();rejectRequest(Error('Unknown delivery'));await screen.findByRole('button',{name:'Retry the same request'});expect(screen.queryByRole('heading',{name:'Request saved'})).toBeNull();expect(heading).not.toHaveFocus();expect(screen.queryByRole('heading',{name:'Test booking confirmed'})).toBeNull();
});

it('V5 payment loading and failure do not focus or announce a confirmed receipt',async()=>{
 vi.stubGlobal('location',{protocol:'https:'});let rejectPayment!:(error:Error)=>void;const payment=vi.fn(()=>new Promise<Response>((_resolve,reject)=>rejectPayment=reject)),transport=fieldTransport(undefined,payment);vi.stubGlobal('fetch',transport);render(<HostedFlow installationId={id} apiUrl="https://api.example"/>);await fillFieldRequest();fireEvent.click(screen.getByRole('button',{name:'Send unconfirmed request'}));const saved=await screen.findByRole('heading',{name:'Request saved'});expect(saved).toHaveFocus();fireEvent.click(screen.getByRole('button',{name:'Reserve selected time'}));const pay=await screen.findByRole('button',{name:'Make staging test payment'});pay.focus();fireEvent.click(pay);await waitFor(()=>expect(payment).toHaveBeenCalledOnce());expect(saved).not.toHaveFocus();expect(screen.queryByRole('heading',{name:'Test booking confirmed'})).toBeNull();rejectPayment(Error('Unknown payment delivery'));await screen.findByRole('button',{name:'Retry the same test payment'});expect(saved).not.toHaveFocus();expect(screen.queryByRole('heading',{name:'Test booking confirmed'})).toBeNull();expect(payment).toHaveBeenCalledOnce();
});
